import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { themeToTailwind } from "../src/tokens/theme";

const styles = new URL("../src/styles/", import.meta.url);
const utilities = readFileSync(new URL("utilities.css", styles), "utf8");

const css = `/*
 * Expressive — Tailwind v4 bridge.
 * Maps --ex-* theme variables to utilities (bg-primary, text-title-large,
 * rounded-shape-large, shadow-elevation-2, p-ex-md, ease-spatial-fast, …).
 * Generated by packages/registry/scripts/build-styles.ts — edit utilities.css instead.
 */

${themeToTailwind()}

${utilities}`;

writeFileSync(fileURLToPath(new URL("expressive.css", styles)), css);
console.log("wrote src/styles/expressive.css");
